from pathlib import Path
import duckdb,json,hashlib
H=Path(__file__).resolve().parent
PRIOR=H.parent/'tochno_context_code_resolution_20261013'
SRC='/workspace/scratch/tochno-enrichment-20261013/raw/data/interim/2021_tochno/data_allsettlements_anon_156_v20251217.parquet'
c=duckdb.connect();c.execute('set threads=1')
# Only the78 held candidate rows and six Parquet fields; no wide raw-attribute read.
c.execute("create temp table t as select * from read_csv(?,header=true,all_varchar=true,delim=',',quote='\"',escape='\"')",[str(PRIOR/'held_context_rows.csv')])
c.execute("""create temp table m as select file_row_number+1 row1,object_level,object_name,region,mun_upper,oktmo,case when regexp_full_match(oktmo,'[0-9]{7,8}') then lpad(oktmo,8,'0') else null end code8 from read_parquet(?,file_row_number=true) where object_level in ('Муниципалитет верхнего уровня','Муниципалитет нижнего уровня')""",[SRC])
# All already-qualified source-name hits are examined, including differing/invalid codes.
c.execute("""create temp table claims as select t.source_record_id,t.municipality_role,m.row1 municipality_frozen_row_1based,m.oktmo municipality_oktmo_raw,m.code8 municipality_oktmo_code8,m.object_level municipality_object_level,m.object_name municipality_label_raw,m.region region_raw,m.mun_upper source_mun_upper_raw from t join m on m.region=t.region_raw and m.object_level=case when t.municipality_role='upper' then 'Муниципалитет верхнего уровня' else 'Муниципалитет нижнего уровня' end and ((t.municipality_role='upper' and m.object_name=t.np_mun_upper_raw) or (t.municipality_role='lower' and m.object_name=t.np_mun_lower_raw and m.mun_upper=t.np_mun_upper_raw))""")
c.execute("""create temp table g as select source_record_id,municipality_role,count(*) source_claim_rows,count(distinct municipality_oktmo_code8) distinct_parent_codes,count(*) filter(where municipality_oktmo_code8 is null) invalid_code_rows,min(municipality_oktmo_code8) municipality_oktmo_code8,list(municipality_frozen_row_1based order by municipality_frozen_row_1based) all_municipality_source_row1_claims from claims group by 1,2""")
c.execute("""create temp table accepted as select t.*,g.source_claim_rows,g.distinct_parent_codes,g.municipality_oktmo_code8,g.all_municipality_source_row1_claims,'verified_parent_code_multiple_source_claims' context_status,true municipality_source_row_ambiguous,false municipality_raw_attribute_row_selected,false boundary_comparability_asserted,'Российская Федерация' country_raw,'RU_OKTMO' code_namespace,'v20251217' source_dataset_version,2021 source_census_year,true administrative_effective_date_unknown,false historical_membership_asserted from t join g using(source_record_id,municipality_role) where g.source_claim_rows>1 and g.distinct_parent_codes=1 and g.invalid_code_rows=0 and t.municipality_prefix8=g.municipality_oktmo_code8 and t.code_basis in ('documented_np11_prefix8_existing_municipality','exact_existing_source_code8_no_hierarchy_derivation')""")
c.execute("copy accepted to ? (header,delimiter ',')",[str(H/'accepted_code_context_delta.csv')])
c.execute("copy (select claims.* from claims join accepted using(source_record_id,municipality_role)) to ? (header,delimiter ',')",[str(H/'all_source_claim_rows.csv')])
c.execute("copy (select t.*,g.source_claim_rows,g.distinct_parent_codes,g.invalid_code_rows,'held_parent_code_not_unique_or_not_proved' final_reason from t left join g using(source_record_id,municipality_role) anti join accepted a using(source_record_id,municipality_role)) to ? (header,delimiter ',')",[str(H/'held_code_context.csv')])
counts=c.execute('select municipality_role,count(*),sum(np_population::bigint),sum(source_claim_rows),count(distinct municipality_oktmo_code8) from accepted group by 1 order by 1').fetchall()
receipt={'input_context_receipt':str(PRIOR/'receipt.json'),'inherited_source_pins':json.loads((PRIOR/'receipt.json').read_text())['inputs'],'candidate_input_sha256':hashlib.sha256((PRIOR/'held_context_rows.csv').read_bytes()).hexdigest(),'code_structure_evidence':str(PRIOR/'code_structure_excerpt.txt'),'target_rows':c.execute('select count(*) from t').fetchone()[0],'accepted':[{'role':x,'np_records':n,'np_population':p,'preserved_source_claim_rows':v,'distinct_parent_codes':z} for x,n,p,v,z in counts],'held_rows':c.execute('select count(*) from t anti join accepted using(source_record_id,municipality_role)').fetchone()[0],'semantics':{'association':'unique existing parent code; source-row provenance remains multiple','choose_census_municipality_attribute_row':False,'boundary_comparability_asserted':False,'historical_membership_asserted':False,'population_coverage_gain':False,'frozen_bridge_modified':False},'outputs':{}}
for p in [H/'accepted_code_context_delta.csv',H/'all_source_claim_rows.csv',H/'held_code_context.csv']:receipt['outputs'][p.name]={'path':str(p),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
(H/'receipt.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');print(json.dumps(receipt,ensure_ascii=False))
